  "nct_id": "NCT07881120",
  "phase": "PHASE2/PHASE3",
  "source": "ClinicalTrials.gov",
  "sponsor": "Beeline Medicines Corporation",
  "start_date": "2026-11-03",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "This study is evaluating whether afimetoran, an investigational oral medicine that blocks toll-like receptors 7 and 8 (TLR7/TLR8), can improve skin disease in adults with active cutaneous lupus erythematosus (CLE), with or without systemic lupus, whose disease has not responded to or who cannot tolerate antimalarial therapy. Participants are assigned by chance to receive afimetoran or a matching placebo capsule once daily for 24 weeks, in addition to their existing standard lupus care. Neither participants nor study staff know which treatment is given.\n\nThe study is run in two stages under a single protocol. Stage 1 compares two doses of afimetoran with placebo to select the dose. Stage 2 compares the selected afimetoran dose with placebo to confirm efficacy and safety. After the 24-week placebo-controlled period, all participants receive afimetoran for a further 28 weeks, for a total of 52 weeks of treatment. The main measures of benefit are the change in the CLASI-A skin activity score and the proportion of participants achieving a 70% improvement in that score at Week 24.",
  "title": "Study of Afimetoran in Adults With Cutaneous Lupus Erythematosus"
}

